package com.tregy.backend.service.impl;
import com.tregy.backend.dto.request.*; import com.tregy.backend.dto.response.UserResponseDTO; import com.tregy.backend.exception.AuthException; import com.tregy.backend.model.*; import com.tregy.backend.model.enums.*; import com.tregy.backend.repository.*; import com.tregy.backend.service.*; import com.tregy.backend.service.support.*;
import org.springframework.beans.factory.annotation.Value; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
@Service
public class AuthServiceImpl implements AuthService{
 private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(AuthServiceImpl.class);
 private final AppUserRepository users;private final DeviceRepository devices;private final EmailVerificationTokenRepository verifications;private final PasswordResetTokenRepository resets;private final RefreshTokenService refreshes;private final JwtService jwt;private final PasswordEncoder passwords;private final EmailService email;private final Clock clock;private final String publicUrl;private final String equalizer;
 public AuthServiceImpl(AppUserRepository users,DeviceRepository devices,EmailVerificationTokenRepository verifications,PasswordResetTokenRepository resets,RefreshTokenService refreshes,JwtService jwt,PasswordEncoder passwords,EmailService email,Clock clock,@Value("${app.public-url:tregy://}")String publicUrl){this.users=users;this.devices=devices;this.verifications=verifications;this.resets=resets;this.refreshes=refreshes;this.jwt=jwt;this.passwords=passwords;this.email=email;this.clock=clock;this.publicUrl=publicUrl.endsWith("/")?publicUrl.substring(0,publicUrl.length()-1):publicUrl;this.equalizer=passwords.encode(TokenHashing.generateRawToken());}
 @Override @Transactional public UserResponseDTO register(RegisterRequestDTO r){validatePassword(r.password());String normalized=normalize(r.email());if(users.existsByEmail(normalized))throw new AuthException("EMAIL_ALREADY_EXISTS","An account with this email already exists");Instant now=Instant.now(clock);AppUser u=new AppUser();u.setEmail(normalized);u.setPasswordHash(passwords.encode(r.password()));u.setUiLanguage(r.uiLanguage());u.setCreatedAt(now);u.setUpdatedAt(now);u=users.save(u);upsertDevice(u.getId(),r.installationId(),now);sendVerification(u,now);return response(u);}
 @Override @Transactional public void verifyEmail(String raw){Instant now=Instant.now(clock);EmailVerificationToken t=verifications.findForUpdate(TokenHashing.sha256Hex(raw)).filter(x->x.usableAt(now)).orElseThrow(this::invalidLink);AppUser u=users.findById(t.getUserId()).orElseThrow(this::invalidLink);t.setUsedAt(now);u.setEmailVerifiedAt(now);verifications.save(t);users.save(u);}
 @Override @Transactional public void resendVerification(String value){users.findByEmail(normalize(value)).filter(u->u.getEmailVerifiedAt()==null).ifPresent(u->sendVerification(u,Instant.now(clock)));}
 @Override @Transactional public AuthSession login(LoginRequestDTO r){Optional<AppUser> found=users.findByEmail(normalize(r.email()));if(found.isEmpty()){passwords.matches(r.password(),equalizer);throw credentials();}AppUser u=found.get();if(!passwords.matches(r.password(),u.getPasswordHash()))throw credentials();boolean cancelled=false;if(u.getDeletionRequestedAt()!=null){/* Signing in with the password cancels a requested deletion (ADR 0009). */u.setDeletionRequestedAt(null);users.save(u);cancelled=true;log.info("account_deletion_cancelled userId={}",u.getId());}Device d=upsertDevice(u.getId(),r.installationId(),Instant.now(clock));return session(u,d.getId(),cancelled);}
 @Override @Transactional(noRollbackFor=AuthException.class) public AuthSession refresh(String raw){RefreshRotation rotation=refreshes.rotate(raw);AppUser u=users.findById(rotation.userId()).orElseThrow(this::credentials);return new AuthSession(jwt.generateAccessToken(u),rotation.refreshToken(),response(u),false);}
 @Override public void logout(String raw){refreshes.revoke(raw);}
 @Override @Transactional public void logoutAll(String userId){AppUser u=requireUser(userId);u.setTokenVersion(u.getTokenVersion()+1);users.save(u);refreshes.revokeAll(userId);}
 @Override @Transactional public void forgotPassword(String value){users.findByEmail(normalize(value)).ifPresent(u->{Instant now=Instant.now(clock);resets.deleteUnused(u.getId());String raw=TokenHashing.generateRawToken();PasswordResetToken t=new PasswordResetToken();t.setUserId(u.getId());t.setTokenHash(TokenHashing.sha256Hex(raw));t.setExpiresAt(now.plus(Duration.ofHours(1)));t.setCreatedAt(now);resets.save(t);email.sendPasswordReset(u.getEmail(),publicUrl+"/reset-password?token="+raw);});}
 @Override @Transactional public void resetPassword(ResetPasswordRequestDTO r){validatePassword(r.newPassword());Instant now=Instant.now(clock);PasswordResetToken t=resets.findForUpdate(TokenHashing.sha256Hex(r.token())).filter(x->x.usableAt(now)).orElseThrow(this::invalidLink);AppUser u=users.findById(t.getUserId()).orElseThrow(this::invalidLink);t.setUsedAt(now);u.setPasswordHash(passwords.encode(r.newPassword()));u.setTokenVersion(u.getTokenVersion()+1);resets.save(t);users.save(u);refreshes.revokeAll(u.getId());}
 private AuthSession session(AppUser u,String deviceId,boolean deletionCancelled){return new AuthSession(jwt.generateAccessToken(u),refreshes.issue(u.getId(),deviceId),response(u),deletionCancelled);}
 private Device upsertDevice(String userId,String installation,Instant now){Device d=devices.findByUserIdAndInstallationId(userId,installation).orElseGet(()->{Device x=new Device();x.setUserId(userId);x.setInstallationId(installation);x.setPlatform(DevicePlatform.ANDROID);x.setCreatedAt(now);return x;});d.setLastSeenAt(now);return devices.save(d);}
 private void sendVerification(AppUser u,Instant now){verifications.deleteUnused(u.getId());String raw=TokenHashing.generateRawToken();EmailVerificationToken t=new EmailVerificationToken();t.setUserId(u.getId());t.setTokenHash(TokenHashing.sha256Hex(raw));t.setExpiresAt(now.plus(Duration.ofHours(24)));t.setCreatedAt(now);verifications.save(t);email.sendVerification(u.getEmail(),publicUrl+"/verify-email?token="+raw);}
 private AppUser requireUser(String id){return users.findById(id).orElseThrow(this::credentials);} private static String normalize(String e){return e.strip().toLowerCase(Locale.ROOT);}
 private static void validatePassword(String p){if(p.getBytes(StandardCharsets.UTF_8).length>72)throw new AuthException("VALIDATION_FAILED","Password must be at most 72 UTF-8 bytes");}
 private AuthException credentials(){return new AuthException("INVALID_CREDENTIALS","Invalid email or password");}private AuthException invalidLink(){return new AuthException("INVALID_TOKEN","This link is invalid or has expired");}
 static UserResponseDTO response(AppUser u){return new UserResponseDTO(u.getId(),u.getEmail(),u.getUiLanguage(),u.getPlatformRole(),u.getEmailVerifiedAt());}
}
